branch_shas=set()
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x1f%B%x1e', f'origin/friend/{b}'], text=True)
    for chunk in out.split('\x1e'):
        if not chunk.strip(): continue
        sha, msg = chunk.split('\x1f',1)
        sha=sha.strip()
        if re.search(r'^Friend-Message:\s*1\s*$', msg, re.M):
            branch_shas.add(sha)
main_shas=set()
for root,_,files in os.walk('.'):
    for f in files:
        if f.endswith('.md') and root.startswith('./S'):
            p=os.path.join(root,f)
            for line in open(p):
                m=re.search(r'friend/\w+ @ ([0-9a-f]{40})', line)
                if m: main_shas.add(m.group(1))
print("missing:", len(branch_shas-main_shas))
